<?php require_once __DIR__.'/config/db.php'; if($_SERVER['REQUEST_METHOD']==='POST') verify_csrf(); if(!isset($_SESSION['cart']))$_SESSION['cart']=[];$id=(int)($_POST['product_id']??$_GET['product_id']??0);$action=$_POST['action']??$_GET['action']??'';$s=$pdo->prepare('SELECT id,name,stock FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if($p&&in_array($action,['add','remove','minus'],true)){if($action==='add'){if((int)$p['stock']<1){flash('error','Product is out of stock.');}else{$_SESSION['cart'][$id]=min((int)$p['stock'],((int)($_SESSION['cart'][$id]??0))+1);}}elseif($action==='minus'){$_SESSION['cart'][$id]=max(0,((int)($_SESSION['cart'][$id]??0))-1);if($_SESSION['cart'][$id]===0)unset($_SESSION['cart'][$id]);}else unset($_SESSION['cart'][$id]);}if($_SERVER['REQUEST_METHOD']==='POST'){header('Content-Type:application/json');echo json_encode(['ok'=>true,'count'=>cart_count(),'total'=>cart_total($pdo)]);exit;}redirect('cart.php');
